<?php

declare(strict_types=1);

namespace WorkerAdmin\Infrastructure\Persistence;

use RuntimeException;
use WorkerAdmin\Contracts\OrderPricingRepository;
use WorkerAdmin\Core\Database;
use WorkerAdmin\Domain\Order\OrderOperationException;
use WorkerAdmin\Domain\Order\PlatformOrderSettlementPolicy;

final class DatabaseOrderPricingRepository implements OrderPricingRepository
{
    private Database $db;
    private PlatformOrderSettlementPolicy $settlementPolicy;
    public function __construct(Database $db){$this->db=$db;$this->settlementPolicy=new PlatformOrderSettlementPolicy();}
    public function updateActualQuantities(array $actor,array $order,array $items):array
    {
        $workerId=(int)($actor['worker_id']??0);if($workerId<1)throw new OrderOperationException('请先完成师傅入驻并登录师傅身份','WORKER_REQUIRED',403);if((string)($order['order_source_type']??'')!=='platform')throw new OrderOperationException('只有平台承接单支持按实际用量重算','PLATFORM_ORDER_REQUIRED',409);if(!$items)throw new OrderOperationException('请填写需要核对的实际数量','PLATFORM_PRICING_ITEMS_REQUIRED',422);
        return $this->db->transaction(function(Database $db)use($order,$items,$workerId):array{$locked=$db->fetch("SELECT o.*,t.customer_flow_mode,t.customer_pricing_mode,t.customer_contract_total_cents,t.booking_paid_cents,t.worker_settlement_mode,t.worker_labor_cents,t.settlement_status FROM orders o INNER JOIN order_platform_terms t ON t.order_id=o.id WHERE o.id=:order_id AND o.order_source_type='platform' FOR UPDATE",['order_id'=>$order['id']]);if(!$locked)throw new OrderOperationException('平台承接单不存在','PLATFORM_ORDER_NOT_FOUND',404);if((int)($locked['booking_fee_cents']??0)!==0)throw new OrderOperationException('平台单仍含普通预约费字段，请先核对订单资金来源','PLATFORM_BOOKING_FLOW_INVALID',409);$externalPrepayment=(new PlatformOrderBookingPaymentVerifier())->verifiedPaidCents($db,(int)$locked['id'],(int)$locked['customer_contract_total_cents'],(int)$locked['booking_paid_cents'],(string)$locked['customer_flow_mode']);if((string)$locked['customer_pricing_mode']!=='itemized')throw new OrderOperationException('固定总价平台单不支持修改实际数量','PLATFORM_ITEMIZED_REQUIRED',409);if((string)$locked['lifecycle_status']!=='active'||in_array((string)$locked['fulfillment_status'],['submitted','accepted'],true)||(string)$locked['settlement_status']!=='pending')throw new OrderOperationException('订单已进入完工或结算阶段，不能再修改实际数量','PLATFORM_PRICING_LOCKED',409);if((int)($locked['assigned_worker_id']??0)!==$workerId||empty($locked['current_assignment_id']))throw new OrderOperationException('只有本单成交师傅可以核对实际数量','FORBIDDEN',403);$assignment=$db->fetch("SELECT id,status,worker_id FROM assignments WHERE id=:assignment_id AND order_id=:order_id AND worker_id=:worker_id FOR UPDATE",['assignment_id'=>$locked['current_assignment_id'],'order_id'=>$locked['id'],'worker_id'=>$workerId]);if(!$assignment||(string)$assignment['status']!=='accepted')throw new OrderOperationException('当前接单关系已变化，请刷新后重试','ASSIGNMENT_CHANGED',409);$rows=$db->fetchAll("SELECT id,description,quantity,unit,unit_price_cents,amount_cents,sort_order FROM order_pricing_items WHERE order_id=:order_id AND item_source='base' AND status='active' ORDER BY sort_order,id FOR UPDATE",['order_id'=>$locked['id']]);if(!$rows)throw new OrderOperationException('本单没有可按实际用量核对的基础计价项目','PLATFORM_PRICING_ITEMS_MISSING',409);$bySort=[];foreach($rows as $row){$sort=(int)$row['sort_order'];if(isset($bySort[$sort]))throw new RuntimeException('平台承接单计价项目排序重复，请联系管理员修复');$bySort[$sort]=$row;}$changed=[];foreach($items as $item){$sort=(int)($item['sort_order']??0);if(!isset($bySort[$sort]))throw new OrderOperationException('计价项目已变化，请刷新订单后重试','PLATFORM_PRICING_ITEM_CHANGED',409);$row=$bySort[$sort];$unitPrice=$row['unit_price_cents']===null?-1:(int)$row['unit_price_cents'];if($unitPrice<0)throw new OrderOperationException('该项目没有可计算单价，不能按实际数量重算','PLATFORM_UNIT_PRICE_MISSING',409);$quantityMilli=(int)($item['quantity_milli']??0);if($quantityMilli<=0||$quantityMilli>999999999999)throw new OrderOperationException('实际数量超出允许范围','PLATFORM_QUANTITY_INVALID',422);$amount=intdiv($quantityMilli*$unitPrice+500,1000);if($amount<0||$amount>100000000)throw new OrderOperationException('重算后的单项金额超出允许范围','PLATFORM_ITEM_TOTAL_INVALID',422);$oldQuantityMilli=$this->decimalToMilli((string)$row['quantity']);if($oldQuantityMilli<0)throw new RuntimeException('平台承接单原计价数量格式异常，请联系管理员核对');$oldAmount=(int)$row['amount_cents'];if($oldQuantityMilli===$quantityMilli&&$oldAmount===$amount)continue;$quantityText=$this->milliToDecimal($quantityMilli);$oldQuantityText=$this->milliToDecimal($oldQuantityMilli);$db->execute("UPDATE order_pricing_items SET quantity=:quantity,amount_cents=:amount,updated_at=UTC_TIMESTAMP() WHERE id=:id AND order_id=:order_id AND item_source='base' AND status='active'",['quantity'=>$quantityText,'amount'=>$amount,'id'=>$row['id'],'order_id'=>$locked['id']]);$changed[]=['sort_order'=>$sort,'description'=>(string)$row['description'],'unit'=>(string)($row['unit']??''),'unit_price_cents'=>$unitPrice,'old_quantity'=>$oldQuantityText,'new_quantity'=>$quantityText,'old_amount_cents'=>$oldAmount,'new_amount_cents'=>$amount];}if(!$changed)throw new OrderOperationException('实际数量与当前记录一致，无需修改','PLATFORM_QUANTITY_UNCHANGED',409);$newTotal=(int)$db->fetchValue("SELECT COALESCE(SUM(amount_cents),0) FROM order_pricing_items WHERE order_id=:order_id AND status='active'",['order_id'=>$locked['id']]);if($newTotal<$externalPrepayment||$newTotal>100000000)throw new OrderOperationException('重算后的客户金额低于外部已收预付款或超出允许范围','PLATFORM_CUSTOMER_TOTAL_INVALID',409);if((string)$locked['worker_settlement_mode']===PlatformOrderSettlementPolicy::MODE_WORKER_COLLECT&&(int)$locked['worker_labor_cents']>0)$this->settlementPolicy->settlement($newTotal,(int)$locked['worker_labor_cents'],$externalPrepayment,PlatformOrderSettlementPolicy::MODE_WORKER_COLLECT);$oldTotal=(int)$locked['customer_contract_total_cents'];$db->execute("UPDATE order_platform_terms SET customer_contract_total_cents=:total,updated_at=UTC_TIMESTAMP() WHERE order_id=:order_id",['total'=>$newTotal,'order_id'=>$locked['id']]);$db->execute("UPDATE orders SET final_amount_cents=:total,updated_at=UTC_TIMESTAMP(),version=version+1 WHERE id=:order_id",['total'=>$newTotal,'order_id'=>$locked['id']]);$payload=['old_customer_total_cents'=>$oldTotal,'new_customer_total_cents'=>$newTotal,'external_prepayment_cents'=>$externalPrepayment,'changes'=>$changed,'message'=>'师傅已按原约定单价核对实际施工数量；本次仅重算客户金额，不属于加价申请'];$json=json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$eventId=$db->insert("INSERT INTO order_events(order_id,event_type,actor_type,actor_id,payload_json,created_at) VALUES(:order_id,'platform_pricing_quantity_adjusted','worker',:worker_id,:payload,UTC_TIMESTAMP())",['order_id'=>$locked['id'],'worker_id'=>$workerId,'payload'=>is_string($json)?$json:'{}']);\WorkerAdmin\Services\OrderNotificationService::queuePersistedEvent($db,(int)$locked['id'],$eventId,'platform_pricing_quantity_adjusted',$payload);$updatedRows=$db->fetchAll("SELECT description,note,quantity,unit,unit_price_cents,amount_cents,sort_order FROM order_pricing_items WHERE order_id=:order_id AND status='active' ORDER BY sort_order,id",['order_id'=>$locked['id']]);foreach($updatedRows as &$updatedRow){$updatedRow['quantity']=$updatedRow['quantity']===null?null:$this->milliToDecimal($this->decimalToMilli((string)$updatedRow['quantity']));$updatedRow['unit_price_cents']=$updatedRow['unit_price_cents']===null?null:(int)$updatedRow['unit_price_cents'];$updatedRow['amount_cents']=(int)$updatedRow['amount_cents'];$updatedRow['sort_order']=(int)$updatedRow['sort_order'];}unset($updatedRow);return['order_id'=>(string)$locked['public_no'],'old_customer_total_cents'=>$oldTotal,'customer_total_cents'=>$newTotal,'pricing_items'=>$updatedRows,'changed_items'=>$changed];});
    }
    private function decimalToMilli(string $value):int{$value=trim($value);if(!preg_match('/^(\d{1,9})(?:\.(\d{1,3}))?$/D',$value,$parts))return-1;return((int)$parts[1])*1000+(int)str_pad($parts[2]??'',3,'0');}
    private function milliToDecimal(int $milli):string{$whole=intdiv($milli,1000);$fraction=$milli%1000;if($fraction===0)return(string)$whole;return$whole.'.'.rtrim(str_pad((string)$fraction,3,'0',STR_PAD_LEFT),'0');}
}
